package com.example.guitarmes.controller.api;
import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import org.junit.jupiter.api.*; import org.springframework.test.web.servlet.*; import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import com.example.guitarmes.process.partsinstallation.*;
class PartsInstallationWorkItemApiControllerTest { @Test void completeAndUncomplete() throws Exception { var s=mock(PartsInstallationWorkItemApiService.class); var r=new PartsInstallationWorkItemResponse(1L,"COMPLETED",true,"2026/09/17 12:00",1,2,false); when(s.complete(1L)).thenReturn(r); when(s.uncomplete(1L)).thenReturn(new PartsInstallationWorkItemResponse(1L,"NOT_STARTED",false,"-",0,2,false)); MockMvc m=MockMvcBuilders.standaloneSetup(new PartsInstallationWorkItemApiController(s)).build(); m.perform(put("/api/process-work-items/1/complete")).andExpect(status().isOk()).andExpect(jsonPath("$.checked").value(true)).andExpect(jsonPath("$.completedCount").value(1)); m.perform(delete("/api/process-work-items/1/complete")).andExpect(status().isOk()).andExpect(jsonPath("$.checked").value(false)); }}
